<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Reports · {{ $school->name }}</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@600;700;800&display=swap" rel="stylesheet"><style>:root{--ink:#172033;--muted:#687386;--blue:#2563eb;--line:#e5eaf2;--canvas:#f7f9fc;--green:#16845a;--orange:#c55c0a}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:15px "DM Sans",sans-serif}.top{height:72px;padding:0 34px;display:flex;align-items:center;justify-content:space-between;background:#fff;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:11px;font-weight:800}.mark{display:grid;place-items:center;width:36px;height:36px;border-radius:11px;color:#fff;background:var(--blue)}.top span:last-child{color:var(--muted);font-size:13px}.main{max-width:1180px;margin:auto;padding:44px 30px}.eyebrow{color:var(--blue);font-size:11px;font-weight:700;letter-spacing:.13em;text-transform:uppercase}.heading h1{margin:8px 0 8px;font:800 36px/1.1 Manrope,sans-serif;letter-spacing:-.055em}.heading p{color:var(--muted)}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:30px 0 18px}.card{padding:21px;border:1px solid var(--line);border-radius:16px;background:#fff;box-shadow:0 10px 28px #1e315308}.stat span{color:var(--muted);font-size:12px}.stat strong{display:block;margin-top:9px;font:800 30px Manrope,sans-serif;letter-spacing:-.06em}.good{color:var(--green)}.warn{color:var(--orange)}.grid{display:grid;grid-template-columns:1.1fr .9fr;gap:18px}.card h2{margin:0 0 18px;font:800 20px Manrope,sans-serif;letter-spacing:-.04em}.progress{height:10px;overflow:hidden;border-radius:99px;background:#edf0f5}.progress i{display:block;height:100%;background:var(--blue);border-radius:inherit}.legend{display:flex;justify-content:space-between;margin-top:12px;color:var(--muted);font-size:12px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:500px}th,td{text-align:left;padding:13px;border-bottom:1px solid var(--line)}th{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.08em}td{font-size:13px}.pill{display:inline-flex;padding:5px 9px;border-radius:99px;font-size:11px;font-weight:700}.pill.good{background:#ecfdf5}.pill.warn{background:#fff7ed}.empty{color:var(--muted);padding:12px 0}@media(max-width:760px){.top{padding:0 18px}.main{padding:30px 16px}.stats,.grid{grid-template-columns:1fr 1fr}.grid{display:block}.grid .card+ .card{margin-top:18px}}@media(max-width:480px){.stats{grid-template-columns:1fr 1fr}}
</style></head><body><header class="top"><div class="brand"><span class="mark" aria-hidden="true">✦</span><span>eRPH Pro</span></div><span>{{ $school->name }} · Weekly report</span></header><main class="main"><span class="eyebrow">{{ $school->subdomain }} / reports</span><div class="heading"><h1>Submission overview</h1><p>School-wide RPH activity for the current week.</p></div><section class="stats"><div class="card stat"><span>Active teachers</span><strong>{{ $activeTeachers }}</strong></div><div class="card stat"><span>Submitted</span><strong class="good">{{ $submitted }}</strong></div><div class="card stat"><span>Pending action</span><strong class="warn">{{ $pending }}</strong></div><div class="card stat"><span>On time</span><strong>{{ $onTime }}</strong></div></section><div class="grid"><section class="card"><h2>Weekly progress</h2><div class="progress"><i style="width:{{ $activeTeachers ? min(100, round(($submitted / $activeTeachers) * 100)) : 0 }}%"></i></div><div class="legend"><span>{{ $submitted }} of {{ $activeTeachers }} submitted</span><span>{{ $activeTeachers ? round(($submitted / $activeTeachers) * 100) : 0 }}%</span></div><p class="empty">Late submissions this week: <strong>{{ $late }}</strong>. The report is computed from school-owned submission records.</p></section><section class="card"><h2>Audit interpretation</h2><p class="empty">This page is the SSR foundation for the existing DASHBOARD and REPORT tabs. Future filters will include academic week, reviewer group, month and submission status.</p></section></div><section class="card" style="margin-top:18px"><h2>Recent submissions</h2><div class="table-wrap"><table><thead><tr><th>Teacher</th><th>Week</th><th>Submitted</th><th>Status</th></tr></thead><tbody>@forelse($recent as $item)<tr><td>{{ $item->teacherProfile->user->name }}</td><td>M{{ $item->week_no }}</td><td>{{ $item->submitted_at->format('d M Y H:i') }}</td><td><span class="pill {{ $item->status === 'on_time' ? 'good' : 'warn' }}">{{ $item->